"""Unit 6: Tagalog Basic Course, Semester I, Unit 2, Chapter 2, Lesson 1: Personal Identification (Family).
Original lessons; the scope follows the DLIFLC Tagalog Basic Course (Teacher Edition, December 2020).
Audio, pictures, partner and group work are left out; the book's answer keys are used where it prints them (one
misprint in its key is corrected and said so), and the English notes are mine."""
from dsl_tl import *


def dd(xs, ans, n=3, extra=()):
    out = []
    for x in list(xs) + list(extra):
        if x != ans and x not in out:
            out.append(x)
    return out[:n]


