        + [F("Siya si Tisoy, ___ ko. (brother-in-law)", "bayaw", ["hipag", "bilas"], "bayaw = brother-in-law."), F("Si Juana ang ___ niya. (sister-in-law)", "hipag", ["bayaw", "bilas"], "hipag = sister-in-law."), F("Sina Gigi at Jojo ang mga ___ nila. (grandchildren)", "apo", ["anak", "pinsan"], "apo = grandchild."), F("Si Goryo ang ___ nila. (stepfather)", "amain", ["madrasta", "tito"], "amain = stepfather."), F("Si Dindi ang ___ niya. (twin)", "kambal", ["pinsan", "apo"], "kambal = twin."), F("Sila ang ___ at lolo mo. (grandmother)", "lola", ["tita", "ate"], "lola = grandmother."), F("Siya ang ___ ko. (mother-in-law or father-in-law)", "biyenan", ["manugang", "asawa"], "biyenan."), F("Si Lucas ang ___ niya. (son-in-law)", "manugang", ["biyenan", "bayaw"], "manugang.")]
