# ------------------------------------------------------------------ 3 Set II personal pronouns
_PR2 = [("ko", "my", "1st person singular"), ("mo", "your", "2nd person singular"), ("niya", "his, her", "3rd person singular"), ("namin", "our (exclusive)", "1st person plural"), ("natin", "our (inclusive)", "1st person plural"), ("ninyo", "your (plural, or singular polite)", "2nd person plural"), ("nila", "their (plural, or singular polite)", "3rd person plural")]
